export const BODY: string = "\n<p>آيفون يلتقط صورًا جميلة ويحفظها في صيغة لا يستطيع نصف العالم فتحها. الحل تحويلها إلى JPG الذي يعمل في كل مكان.</p>\n<p>لا تطبيق لتثبيته، ولا حساب لإنشائه، ولا رفع إلى خادم. التحويل يحدث على جهازك في دقائق.</p>\n<p>يمر هذا الدليل بكل خطوة، من اختيار الصور إلى تنزيل ملفات JPG النهائية.</p>\n<h2 id=\"before-you-start\">قبل أن تبدأ: ما الذي تحتاجه؟</h2>\n<p>قبل أن تبدأ، تحتاج إلى صور HEIC ومعرفة وجهتها. تحقق مما إذا كانت الوجهة تقبل HEIC أم تحتاج إلى JPG.</p>\n<p>إذا كانت صورك Live Photos، فتذكر أن التحويل إلى JPG يحفظ الصورة الثابتة فقط ويفقد الفيديو القصير.</p>\n<h2 id=\"step-1-open-tool\">الخطوة 1: افتح أداة HEIC إلى JPG</h2>\n<p>افتح <a href=\"/ar/tahwil-heic-ila-jpg/\">أداة HEIC إلى JPG</a> في متصفحك. تعمل الأداة بالكامل على جهازك دون رفع الصور إلى أي خادم.</p>\n<p>لا حاجة إلى حساب أو تثبيت. افتح الصفحة وابدأ فورًا، وستبقى صورك خاصة طوال العملية.</p>\n<h2 id=\"step-2-upload\">الخطوة 2: ارفع صور HEIC</h2>\n<p>ارفع صور HEIC: أسقطها في منطقة الرفع أو اخترها من جهازك. تُقبل ملفات HEIC بأي حجم معقول.</p>\n<p>إذا رفعت عدة صور، فستظهر كل واحدة في قائمة. يمكنك تحويلها كلها دفعة واحدة بإعدادات موحدة.</p>\n<h2 id=\"step-3-quality\">الخطوة 3: راجع إعداد الجودة</h2>\n<p>راجع إعداد الجودة: 90 بالمئة هو الإعداد الافتراضي ويوازن بين الحجم والجودة. للصور المهمة استخدم 95.</p>\n<p>لا تخفض الجودة كثيرًا. التحويل بجودة منخفضة يفقد تفاصيل لا يمكن استعادتها لاحقًا.</p>\n<h2 id=\"step-4-convert\">الخطوة 4: حوّل الصور</h2>\n<p>حوّل الصور: اضغط زر التحويل وانتظر حتى تنتهي الأداة. فك تشفير HEIC يستغرق وقتًا أطول قليلًا من الصيغ الأخرى.</p>\n<p>الدفعة المتوسطة تستغرق دقائق معدودة. تابع شريط التقدم وانتظر حتى يكتمل التحويل.</p>\n<h2 id=\"step-5-preview\">الخطوة 5: راجع قبل التنزيل</h2>\n<p>راجع قبل التنزيل: قارن النتيجة بالأصل، وتأكد من أن الألوان صحيحة والاتجاه صحيح والتفاصيل واضحة.</p>\n<p>إذا بدت النتيجة جيدة، فهي جاهزة. وإذا بدت باهتة، فأعد التحويل بجودة أعلى.</p>\n<h2 id=\"step-6-download\">الخطوة 6: نزّل ملفات JPG</h2>\n<p>نزّل ملفات JPG: اضغط زر التنزيل واحفظ الملفات في مجلد جديد. إذا كانت عدة صور، فستنزّل كملف ZIP واحد.</p>\n<p>فك ضغط الملف وراجع النتائج. تحقق من أن كل صورة موجودة وتبدو صحيحة.</p>\n<ol>\n<li>ارفع صور HEIC.</li>\n<li>راجع إعداد الجودة.</li>\n<li>حوّل الصور.</li>\n<li>نزّل ملفات JPG.</li>\n</ol>\n<h2 id=\"converting-on-iphone\">كيف تحوّل مباشرة على آيفون؟</h2>\n<p>للتحويل مباشرة على آيفون، افتح الأداة في متصفح سفاري وارفع الصور من معرضك. التحويل يحدث على جهازك دون حاسوب.</p>\n<p>على آيفون، اختر الصور من المعرض مباشرة. لا حاجة إلى نقلها إلى حاسوب أولًا.</p>\n<h2 id=\"converting-a-whole-album\">كيف تحوّل ألبومًا كاملًا دفعة واحدة؟</h2>\n<p>لتحويل ألبوم كامل دفعة واحدة، ارفع كل صور الألبوم وحوّلها بإعدادات موحدة. الأداة تحوّل الدفعة كاملة وتنزّلها كملف ZIP.</p>\n<p>سمِّ المجلد باسم الألبوم بعد التنزيل. التنظيم الجيد يسهّل العثور على الصور لاحقًا.</p>\n<h2 id=\"after-converting\">بعد التحويل: ماذا تفعل الآن؟</h2>\n<p>بعد التحويل، احتفظ بالملفات الأصلية HEIC كنسخة احتياطية. قد تحتاجها إذا غيّرت رأيك بشأن الجودة أو الصيغة.</p>\n<p>وللأحجام الصغيرة بعد التحويل، استخدم <a href=\"/ar/daght-as-sura-ila-100kb/\">ضاغط 100 كيلوبايت</a> أو <a href=\"/ar/daght-as-sura-ila-hajm-muayyan/\">ضاغط حجم الملف المستهدف</a>، أو حوّل إلى WebP باستخدام <a href=\"/ar/tahwil-jpg-ila-webp/\">محول JPG إلى WebP</a>.</p>\n<h2 id=\"fixing-problems\">كيف تحل المشاكل الشائعة؟</h2>\n<p>لحل المشاكل الشائعة، افحص السبب أولًا. الملف الذي يفشل في التحويل قد يكون تالفًا، والألوان الباهتة تعني جودة منخفضة.</p>\n<p>أعد التحويل من الملف الأصلي بإعدادات مختلفة. لا تعيد التحويل من النسخة المحوّلة، لأن كل جولة تضيف ضررًا.</p>\n<h2 id=\"stop-heic-future\">كيف تمنع HEIC في الصور المستقبلية؟</h2>\n<p>لمنع HEIC في الصور المستقبلية، غيّر إعدادات الكاميرا في آيفون إلى الأكثر توافقًا. بهذا تحفظ الصور الجديدة كـJPG مباشرة.</p>\n<p>الإعداد في الكاميرا ثم الصيغ ثم الأكثر توافقًا. الصور الجديدة ستكون JPG، والصور القديمة تبقى HEIC حتى تحوّلها.</p>\n<h2 id=\"photos-in-messages\">كيف تحوّل صورًا مستلمة في رسائل؟</h2>\n<p>لتحويل صور مستلمة في رسائل، احفظها في معرضك أولًا ثم ارفعها إلى الأداة. الصور المستلمة عبر واتساب أو تليغرام قد تكون مضغوطة أصلًا.</p>\n<p>إذا كانت الصورة المستلمة صغيرة جدًا، فلا تتوقع جودة عالية بعد التحويل. ابدأ من النسخة الأصلية كلما أمكن.</p>\n<h2 id=\"heic-on-windows\">كيف تحوّل ملفات HEIC على ويندوز؟</h2>\n<p>لتحويل ملفات HEIC على ويندوز، افتح الأداة في متصفحك وارفع الملفات. لا حاجة إلى تثبيت برنامج إضافي لدعم HEIC.</p>\n<p>المتصفح يفك تشفير HEIC تلقائيًا. هذه أسهل طريقة لتحويل HEIC على ويندوز دون برامج.</p>\n<h2 id=\"heic-for-job-application\">كيف تحوّل HEIC لطلب توظيف؟</h2>\n<p>لتحويل HEIC لطلب توظيف، حوّل الصورة إلى JPG بجودة عالية. البوابات تقبل JPG دائمًا، بينما ترفض HEIC غالبًا.</p>\n<p>تحقق من أبعاد الصورة المطلوبة أيضًا. بعض البوابات تطلب أبعادًا محددة بالإضافة إلى الصيغة.</p>\n<h2 id=\"keeping-converted-copies-organised\">كيف تحافظ على النسخ المحوّلة منظمة؟</h2>\n<p>للحفاظ على النسخ المحوّلة منظمة، أنشئ مجلدًا لكل ألبوم أو مناسبة. سمِّ الملفات بوضوح حسب المحتوى والتاريخ.</p>\n<p>احتفظ بالملفات الأصلية HEIC في مجلد منفصل. التنظيم الجيد يمنع الخلط بين النسخ.</p>\n<h2 id=\"heic-for-social-media\">كيف تحوّل HEIC لوسائل التواصل؟</h2>\n<p>لتحويل HEIC لوسائل التواصل، حوّل إلى JPG قبل الرفع. معظم المنصات تقبل JPG دون مشاكل، بينما HEIC قد يُرفض أو يُضغط بشكل سيئ.</p>\n<p>وللتفاصيل الكاملة، اقرأ <a href=\"/ar/blog/dalil-tahwil-heic-ila-jpg/\">الدليل الكامل لتحويل HEIC إلى JPG</a> و<a href=\"/ar/blog/heic-vs-jpg/\">HEIC مقابل JPG</a>، أو جرّب <a href=\"/ar/tahwil-as-suwar/\">محول الصور</a> لصيغ أخرى.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"كيف أحوّل HEIC إلى JPG على آيفون دون حاسوب؟","answer":"افتح الأداة في متصفح سفاري على آيفون وارفع الصور من معرضك. التحويل يحدث على جهازك دون حاسوب."},{"question":"هل يمكنني تحويل HEIC إلى JPG بالجملة على ويندوز؟","answer":"نعم، ارفع كل صور HEIC دفعة واحدة وحوّلها بإعدادات موحدة. الأداة تحوّل الدفعة كاملة وتنزّلها كملف ZIP."},{"question":"لماذا يبدو ملف JPG المحوّل أكبر بالميغابايت من HEIC؟","answer":"لأن JPG أقل كفاءة في الضغط من HEIC. الصورة نفسها تحتاج مساحة أكبر بصيغة JPG، وهذا طبيعي وليس خطأ."},{"question":"ماذا يحدث للصور الحية عند تحويل HEIC إلى JPG؟","answer":"عند التحويل إلى JPG، تحصل على الصورة الثابتة فقط ويفقد الفيديو القصير. إذا أردت الاحتفاظ بالحركة، فحوّل Live Photo إلى فيديو أو GIF."},{"question":"هل يمكنني تحويل HEIC إلى JPG دون فقدان تاريخ الصورة؟","answer":"نعم، التحويل يحافظ على تاريخ الصورة وبياناتها الأساسية. يزيل فقط بيانات الموقع لأسباب تتعلق بالخصوصية."},{"question":"هل توجد طريقة لتحويل ملفات HEIC التي فشلت بسبب خطأ؟","answer":"تحقق أولًا من أن الملف يفتح في تطبيق الصور. إذا كان تالفًا، فأعد تنزيله من النسخة الاحتياطية. وإذا كان الملف سليمًا، فجرّب تحويله وحده بدل دفعة."}];
